def on_part_end(self) -> None:
    message = (MultiPartMessage.PART_END, b"")
    self.messages.append(message)

def match_tag_start(self):
    match = self.match(
        r"""
        \<%     # opening tag

        ([\w\.\:]+)   # keyword

        ((?:\s+\w+|\s*=\s*|".*?"|'.*?')*)  # attrname, = \
                                           #        sign, string expression

        \s*     # more whitespace

        (/)?>   # closing

        """,
        re.I | re.S | re.X,
    )

    if not match:
        return False

    keyword, attr, isend = match.groups()
    self.keyword = keyword
    attributes = {}
    if attr:
        for att in re.findall(
            r"\s*(\w+)\s*=\s*(?:'([^']*)'|\"([^\"]*)\")", attr
        ):
            key, val1, val2 = att
            text = val1 or val2
            text = text.replace("\r\n", "\n")
            attributes[key] = text
    self.append_node(parsetree.Tag, keyword, attributes)
    if isend:
        self.tag.pop()
    elif keyword == "text":
        match = self.match(r"(.*?)(?=\</%text>)", re.S)
        if not match:
            raise exceptions.SyntaxException(
                "Unclosed tag: <%%%s>" % self.tag[-1].keyword,
                **self.exception_kwargs,
            )
        self.append_node(parsetree.Text, match.group(1))
        return self.match_tag_end()
    return True

def __init__(self, *args, view_name=None, view_description=None, **kwargs):
    super().__init__(*args, **kwargs)

    self.view_name = view_name
    if view_name and not view_description:
        view_description = f"{view_name} API root view"
    self.view_description = view_description

    # Extend the list view mappings to support the DELETE operation
    self.routes[0].mapping.update(
        {
            "put": "bulk_update",
            "patch": "bulk_partial_update",
            "delete": "bulk_destroy",
        }
    )

def login(self, login, password, url=None):
    """login page
    """
    auth = self._auth(login, password)
    cherrypy.session['isadmin'] = auth['isadmin']
    cherrypy.session['connected'] = auth['connected']

    if auth['connected']:
        if auth['isadmin']:
            message = \
                "login success for user '%(user)s' as administrator" % {
                    'user': login
                }
        else:
            message = \
                "login success for user '%(user)s' as normal user" % {
                    'user': login
                }
        cherrypy.log.error(
            msg=message,
            severity=logging.INFO
        )
        cherrypy.session[SESSION_KEY] = cherrypy.request.login = login
        if url is None:
            redirect = "/"
        else:
            redirect = base64.b64decode(url)
        raise cherrypy.HTTPRedirect(redirect)
    else:
        message = "login failed for user '%(user)s'" % {
            'user': login
        }
        cherrypy.log.error(
            msg=message,
            severity=logging.WARNING
        )
        if url is None:
            qs = ''
        else:
            qs = '?url=' + url
        raise cherrypy.HTTPRedirect("/signin" + qs)

