            stacklevel=2
        )

    g.build_lritems()
    g.compute_first()
    g.compute_follow()

    cache_file = os.path.join(
        tempfile.gettempdir(),
        "rply-%s-%s-%s.json" % (self.VERSION, self.cache_id, self.compute_grammar_hash(g))
